package com.bank.vending;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

class Product {
    final String code, name; final BigDecimal price;
    Product(String code, String name, BigDecimal price) { this.code = code; this.name = name; this.price = price; }
}

class Slot {
    final Product product; int count;
    Slot(Product p, int count) { this.product = p; this.count = count; }
}

interface MachineState {
    void insertMoney(VendingMachine m, BigDecimal amt);
    void select(VendingMachine m, String code);
}

class IdleState implements MachineState {
    public void insertMoney(VendingMachine m, BigDecimal amt) { m.addBalance(amt); m.setState(new SelectingState()); }
    public void select(VendingMachine m, String code) { m.log("Insert money first"); }
}

class SelectingState implements MachineState {
    public void insertMoney(VendingMachine m, BigDecimal amt) { m.addBalance(amt); }
    public void select(VendingMachine m, String code) {
        Slot slot = m.slot(code);
        if (slot == null || slot.count == 0) { m.log("Out of stock"); return; }
        if (m.balance().compareTo(slot.product.price) < 0) { m.log("Insufficient money"); return; }
        m.setState(new DispensingState());
        m.dispense(slot);
    }
}

class DispensingState implements MachineState {
    public void insertMoney(VendingMachine m, BigDecimal amt) { m.log("Dispensing, wait"); }
    public void select(VendingMachine m, String code) { m.log("Dispensing, wait"); }
}

class VendingMachine {
    private static final Logger log = Logger.getLogger("VEND");
    private final Map<String, Slot> slots = new HashMap<>();
    private MachineState state = new IdleState();
    private BigDecimal balance = BigDecimal.ZERO;
    void addSlot(Slot s) { slots.put(s.product.code, s); }
    Slot slot(String code) { return slots.get(code); }
    void setState(MachineState s) { state = s; }
    void addBalance(BigDecimal amt) { balance = balance.add(amt); }
    BigDecimal balance() { return balance; }
    void log(String msg) { log.info(msg); }

    void insertMoney(BigDecimal amt) { state.insertMoney(this, amt); }
    void select(String code) { state.select(this, code); }

    void dispense(Slot slot) {
        slot.count--;
        BigDecimal change = balance.subtract(slot.product.price);
        log.info("Dispensed " + slot.product.name + ", change=" + change);
        balance = BigDecimal.ZERO;
        setState(new IdleState());
    }
}

public class VendingDemo {
    public static void main(String[] args) {
        VendingMachine m = new VendingMachine();
        m.addSlot(new Slot(new Product("A1", "Cheque Book", new BigDecimal("40")), 5));
        m.insertMoney(new BigDecimal("50")); // Rajesh inserts 50
        m.select("A1");                        // buys cheque book, gets 10 change
    }
}
